+          profile: PROGRAM_SEMANTIC_BASELINE_DRAFT_PROFILE,
+          draftId,
+          sourceSessionId: command.sourceSessionId,
+          programStateId,
+          fromProgramStateRevision: state.revision,
+          initialProgramRevisionId,
+          admissionEventId,
+          cut,
