+  forbiddenChangeKinds: string[];
+  omissions: {
+    allowedRepositoryRoots: number;
+    allowedEffectClasses: number;
+    allowedExternalSystems: number;
+    capabilityCeiling: number;
+    mandatoryVerificationIds: number;
+    forbiddenChangeKinds: number;
