+        const oldest = this.completed.keys().next().value as string | undefined;
+        if (oldest !== undefined) this.completed.delete(oldest);
+      }
+      this.completed.set(key, structuredClone(response));
+      await binding.transport.send(response);
+    }
+    return response;
+  }
