+    }
+    const prefix = `${generationId}:`;
+    for (const key of [...this.completed.keys()]) if (key.startsWith(prefix)) this.completed.delete(key);
+    for (const key of [...this.inFlight.keys()]) if (key.startsWith(prefix)) this.inFlight.delete(key);
+  }
