+function clipList(values: readonly string[]): { values: string[]; omitted: number } {
+  return {
+    values: values.slice(0, MAX_AUTHORITY_LIST_ENTRIES),
+    omitted: Math.max(0, values.length - MAX_AUTHORITY_LIST_ENTRIES),
+  };
