+
+function result(
+  message: ProgramRevisionProposalWireV1,
+  outcome: ProgramRevisionProposalResultWireV1["outcome"],
+  extras: Partial<Pick<ProgramRevisionProposalResultWireV1, "draftId" | "draftDigest" | "errorCode" | "error">> = {},
