+  return {
+    type: "program.revision.proposal.result",
+    version: PROGRAM_REVISION_MESSAGE_VERSION,
+    requestId: message.requestId,
+    sessionId: message.sessionId,
+    planningEpisodeId: message.planningEpisodeId,
+    outcome,
+    ...extras,
+  };
+}
+
+function errorText(error: unknown): string {
+  const text = error instanceof Error ? error.message : String(error);
+  const nonempty = text.trim().length === 0 ? "Unknown revision protocol failure" : text;
+  return nonempty.length <= 4096 ? nonempty : `${nonempty.slice(0, 4093)}...`;
