+  let count = 0;
+  for (const key of completed.keys()) if (key.startsWith(prefix)) count += 1;
+  for (const key of inFlight.keys()) if (key.startsWith(prefix)) count += 1;
+  return count >= REVISION_PROTOCOL_REPLAY_MAX;
