+export class ProgramAdaptiveApplicationPortV1 implements ProgramApplicationPortV1 {
+  constructor(
+    private readonly base: ProgramApplicationPortV1,
+    private readonly recovery: ProgramSemanticRecoveryRegistryV1,
+  ) {}
