+      retainedAttemptIds: retained.omitted,
+      invalidatedAttemptIds: invalidated.omitted,
+      modifiedWorkItemIds: modified.omitted,
+      addedWorkItemIds: added.omitted,
+      supersededWorkItemIds: superseded.omitted,
